from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(int)
for name,(cx,cy,rad) in [('blue',(93,57,10)),('yellow',(177,56,10))]:
 print('\\n',name)
 for y in range(cy-rad,cy+rad+1):
  vals=[]
  for x in range(cx-rad,cx+rad+1):
   d=((x-cx)**2+(y-cy)**2)**.5
   if d>rad: vals.append('   ')
   else:
    r,g,b=im[y,x]
    if name=='blue': vals.append(f'{b//10:02d}' if b-r>15 else '..')
    else: vals.append(f'{max(r,g)//10:02d}' if g-b>15 else '..')
  print(f'{y:2d}', ' '.join(vals))
PY"

